    lambda: (lambda Mol: pick([bool(Mol(s).chiral()) and '=O' in s and not s.startswith('O=C') for s in ('CC(=O)CCCC', 'CC(=O)C(C)CC', 'O=CCC(CC)C', 'CC(=O)CC(C)C')], True))(__import__('orgkit').Mol),
